 3	public sealed class RetryPolicy
 4	{
 5	    public bool ShouldRetry(Exception error, int attempt)
 6	    {
 7	        ArgumentNullException.ThrowIfNull(error);
 8	
 9	        if (attempt < 1)
10	        {
11	            throw new ArgumentOutOfRangeException(nameof(attempt));
12	        }
13	
14	        if (attempt >= 3)
15	        {
16	            return false;
17	        }
18	
19	        return error is TimeoutException or IOException;
20	    }
21	}

